const fs = require('fs'); const { fresh, t, tree } = require('./h.cjs');
const d = fresh('w-ds');
fs.mkdirSync(`${d}/full/sub`, { recursive: true }); fs.writeFileSync(`${d}/full/a`, 'a'); fs.writeFileSync(`${d}/full/sub/b`, 'b'); fs.writeFileSync(`${d}/file`, 'f');
t('rmdirSync non-empty', () => fs.rmdirSync(`${d}/full`)); console.log('  tree', tree(d));
t('rmdirSync file', () => fs.rmdirSync(`${d}/file`));
t('rmdirSync recursive non-empty', () => fs.rmdirSync(`${d}/full`, { recursive: true })); console.log('  tree', tree(d));
fs.mkdirSync(`${d}/full/sub`, { recursive: true }); fs.writeFileSync(`${d}/full/a`, 'a');
t('rmSync dir no recursive', () => fs.rmSync(`${d}/full`)); console.log('  tree', tree(d));
t('rmSync empty dir no recursive', () => fs.rmSync(`${d}/full/sub`)); console.log('  tree', tree(d));
t('rmSync missing', () => fs.rmSync(`${d}/nope`));
t('rmSync missing force', () => fs.rmSync(`${d}/nope`, { force: true }));
t('rmSync missing recursive force', () => fs.rmSync(`${d}/nope/deeper`, { recursive: true, force: true }));
t('rmdirSync missing', () => fs.rmdirSync(`${d}/nope`));
t('unlinkSync dir', () => fs.unlinkSync(`${d}/full`)); console.log('  tree', tree(d));
const o = fresh('w-outside'); fs.writeFileSync(`${o}/keep`, 'k'); fs.mkdirSync(`${o}/kd`); fs.writeFileSync(`${o}/kd/k2`, 'k');
fs.mkdirSync(`${d}/r/in`, { recursive: true }); fs.symlinkSync('../../../w-outside', `${d}/r/in/link`); fs.symlinkSync('../w-outside/keep', `${d}/r/flink`);
t('rmSync recursive with symlink to outside', () => fs.rmSync(`${d}/r`, { recursive: true }));
console.log('  ds tree', tree(d), '| outside tree', tree(o));
fs.symlinkSync('../w-outside', `${d}/dlink`);
t('rmSync symlink-to-dir no recursive', () => fs.rmSync(`${d}/dlink`)); console.log('  outside', tree(o), 'ds', tree(d));
fs.symlinkSync('../w-outside', `${d}/dlink2`);
t('rmdirSync symlink-to-dir', () => fs.rmdirSync(`${d}/dlink2`)); console.log('  outside', tree(o));
t('rmSync recursive symlink-to-dir', () => fs.rmSync(`${d}/dlink2`, { recursive: true })); console.log('  outside', tree(o), 'ds', tree(d));
fs.mkdirSync(`${d}/c/s`, { recursive: true }); fs.writeFileSync(`${d}/c/x`, 'x'); fs.writeFileSync(`${d}/c/s/y`, 'y');
t('cpSync into itself', () => fs.cpSync(`${d}/c`, `${d}/c/s/inner`, { recursive: true })); console.log('  tree', tree(`${d}/c`));
t('cpSync onto itself', () => fs.cpSync(`${d}/c`, `${d}/c`, { recursive: true })); console.log('  tree', tree(`${d}/c`));
t('cpSync dir without recursive', () => fs.cpSync(`${d}/c`, `${d}/c2`)); console.log('  exists c2', fs.existsSync(`${d}/c2`));
t('copyFileSync onto itself', () => fs.copyFileSync(`${d}/c/x`, `${d}/c/x`)); console.log('  x', fs.readFileSync(`${d}/c/x`, 'utf8'));
fs.symlinkSync('../../w-outside', `${d}/c/ol`); fs.symlinkSync('x', `${d}/c/xl`);
t('cpSync with symlinks (default)', () => fs.cpSync(`${d}/c`, `${d}/c3`, { recursive: true }));
for (const n of ['ol', 'xl']) { const p = `${d}/c3/${n}`; console.log('  c3', n, fs.lstatSync(p).isSymbolicLink() ? 'symlink -> ' + fs.readlinkSync(p) : 'real ' + (fs.statSync(p).isDirectory() ? 'dir ' + fs.readdirSync(p).sort() : 'file')); }
t('cpSync dereference', () => fs.cpSync(`${d}/c`, `${d}/c4`, { recursive: true, dereference: true }));
for (const n of ['ol', 'xl']) { const p = `${d}/c4/${n}`; console.log('  c4', n, fs.lstatSync(p).isSymbolicLink() ? 'symlink -> ' + fs.readlinkSync(p) : 'real ' + (fs.statSync(p).isDirectory() ? 'dir ' + fs.readdirSync(p).sort() : 'file')); }
t('cpSync verbatimSymlinks', () => fs.cpSync(`${d}/c`, `${d}/c5`, { recursive: true, verbatimSymlinks: true })); console.log('  c5 ol ->', fs.readlinkSync(`${d}/c5/ol`), 'xl ->', fs.readlinkSync(`${d}/c5/xl`));
t('cpSync file symlink alone', () => fs.cpSync(`${d}/c/xl`, `${d}/xl-copy`)); console.log('  xl-copy', fs.lstatSync(`${d}/xl-copy`).isSymbolicLink() ? 'symlink ' + fs.readlinkSync(`${d}/xl-copy`) : 'file');
t('cpSync existing dest errorOnExist', () => fs.cpSync(`${d}/c/x`, `${d}/c/s/y`, { force: false, errorOnExist: true }));
t('cpSync existing dest force false', () => fs.cpSync(`${d}/c/x`, `${d}/c/s/y`, { force: false })); console.log('  y', fs.readFileSync(`${d}/c/s/y`, 'utf8'));
t('cpSync filter', () => fs.cpSync(`${d}/c`, `${d}/c6`, { recursive: true, filter: (s) => !s.endsWith('/x') })); console.log('  c6', tree(`${d}/c6`));
t('cpSync missing src', () => fs.cpSync(`${d}/nope`, `${d}/c7`));
