t('cpSync dangling symlink', () => fs.cpSync(`${d}/cd`, `${d}/cd2`, { recursive: true })); console.log('  cd2', tree(`${d}/cd2`));
t('cpSync dangling symlink dereference', () => fs.cpSync(`${d}/cd`, `${d}/cd3`, { recursive: true, dereference: true })); console.log('  cd3', tree(`${d}/cd3`));
console.log('final outside', tree(o));
